    @Test
    public void testNamespacePointer_delegates_toValuePointer_whenIndexNotWhole() {
        NodePointer valueNs = mock(NodePointer.class);
        NodePointer sentinel = mock(NodePointer.class);

        when(valueNs.namespacePointer("ns")).thenReturn(sentinel);

        DelegatingCollectionPointer cp = new DelegatingCollectionPointer(new ArrayList<Object>(), Locale.getDefault(), valueNs);

        setIndex(cp, 0);

        NodePointer result = cp.namespacePointer("ns");
        assertSame(sentinel, result);
    }

    private int findWholeCollectionValue(CollectionPointer cp) {
        int value = Integer.MIN_VALUE;
        Class<?> cur = cp.getClass();
        while (cur != null) {
            try {
                Field f = cur.getDeclaredField("WHOLE_COLLECTION");
                f.setAccessible(true);
                value = f.getInt(null);
                break;
            } catch (NoSuchFieldException | IllegalAccessException e) {
                // continue searching in superclass
            }
            cur = cur.getSuperclass();
        }
        if (value == Integer.MIN_VALUE) {
            value = -1;
        }
        return value;
    }

    private void setIndex(Object obj, int value) {
        Field f = findField(obj.getClass(), "index");
        if (f == null) {
            throw new RuntimeException("index field not found");
        }
        f.setAccessible(true);
        try {
            f.setInt(obj, value);
        } catch (IllegalAccessException e) {
            throw new RuntimeException(e);
        }
    }

    private Field findField(Class<?> cls, String name) {
        Class<?> cur = cls;
        while (cur != null) {
            try {
                return cur.getDeclaredField(name);
            } catch (NoSuchFieldException e) {
                cur = cur.getSuperclass();
            }
        }
        return null;
    }
}

